ALTER TABLE `user` ADD COLUMN email VARCHAR(320) NULL, ADD COLUMN email_hash VARCHAR(64) NULL,
 ADD COLUMN password_hash VARCHAR(255) NULL, ADD COLUMN gender VARCHAR(16) NULL, ADD COLUMN birthday DATE NULL,
 ADD COLUMN member_level VARCHAR(32) NOT NULL DEFAULT '普通会员', ADD COLUMN points BIGINT NOT NULL DEFAULT 0;
CREATE UNIQUE INDEX uk_user_email_hash ON `user`(email_hash);
CREATE TABLE user_account_binding (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,provider VARCHAR(32) NOT NULL,provider_uid VARCHAR(128) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_binding(provider,provider_uid),KEY idx_binding_user(user_id));
CREATE TABLE user_login_log (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,login_type VARCHAR(32) NOT NULL,ip VARCHAR(64),user_agent VARCHAR(512),success BOOLEAN NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_login_user(user_id,created_at));
CREATE TABLE user_device (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,device_id VARCHAR(128) NOT NULL,device_name VARCHAR(128),last_login_at DATETIME,revoked BOOLEAN NOT NULL DEFAULT FALSE,UNIQUE KEY uk_device(user_id,device_id));
CREATE TABLE user_points_log (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,change_amount BIGINT NOT NULL,balance BIGINT NOT NULL,reason VARCHAR(255),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_points_user(user_id,created_at));
CREATE TABLE user_privacy_setting (user_id BIGINT PRIMARY KEY,profile_authorized BOOLEAN NOT NULL DEFAULT TRUE,push_enabled BOOLEAN NOT NULL DEFAULT TRUE,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE user_feedback (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,content VARCHAR(2000) NOT NULL,contact VARCHAR(320),status VARCHAR(32) NOT NULL DEFAULT 'pending',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
